/* ---- helpers --------------------------------------------------------- */

static Expr* eval_str(const char* input) {
    Expr* e = parse_expression(input);
    ASSERT_MSG(e != NULL, "parse failed: %s", input);
    Expr* r = evaluate(e);
    expr_free(e);
    return r;
}

static double eval_real(const char* input) {
    Expr* r = eval_str(input);
    ASSERT_MSG(r->type == EXPR_REAL, "%s: expected a machine Real", input);
    double v = r->data.real;
    expr_free(r);
    return v;
}

/* Complex[re, im] of machine reals (re, im). */
static void eval_complex(const char* input, double* re, double* im) {
    Expr* r = eval_str(input);
    ASSERT_MSG(r->type == EXPR_FUNCTION && r->data.function.arg_count == 2 &&
               r->data.function.head->type == EXPR_SYMBOL &&
               strcmp(r->data.function.head->data.symbol.name, "Complex") == 0 &&
               r->data.function.args[0]->type == EXPR_REAL &&
               r->data.function.args[1]->type == EXPR_REAL,
               "%s: expected a machine Complex", input);
    *re = r->data.function.args[0]->data.real;
    *im = r->data.function.args[1]->data.real;
    expr_free(r);
}

static void assert_true(const char* input) { assert_eval_eq(input, "True", 0); }

/* A double as a machine-Real literal: %.17g, with a "." forced so that 3.0 is
 * not read back as the exact Integer 3, and the exponent in *^ form. */
static const char* R(double v, char* buf) {
    char t[40];
    snprintf(t, sizeof t, "%.17g", v);
    char* e = strchr(t, 'e');
    if (e) {
        *e = 0;
        snprintf(buf, 64, "%s%s*^%s", t, strchr(t, '.') ? "" : ".", e + 1);
    } else {
        snprintf(buf, 64, "%s%s", t, strchr(t, '.') ? "" : ".");
    }
    return buf;
}

/* 64 ulp, relative to the value (complex: to its modulus). */
#define PCFD_TOL 1.43e-14

/* ---- exact rules ----------------------------------------------------- */

void test_pcfd_exact() {
    assert_true("ParabolicCylinderD[nu, 0] === 2^(nu/2) Sqrt[Pi]/Gamma[1/2 - nu/2]");
    assert_eval_eq("ParabolicCylinderD[0, 0]", "1", 0);
    assert_eval_eq("ParabolicCylinderD[1, 0]", "0", 0);
    assert_eval_eq("ParabolicCylinderD[2, 0]", "-1", 0);
    assert_true("ParabolicCylinderD[1/2, 0] === 2^(1/4) Sqrt[Pi]/Gamma[1/4]");
    /* integer orders and exact arguments stay unevaluated */
    assert_eval_eq("ParabolicCylinderD[2, z]", "ParabolicCylinderD[2, z]", 0);
    assert_eval_eq("ParabolicCylinderD[1, 2]", "ParabolicCylinderD[1, 2]", 0);
    assert_eval_eq("ParabolicCylinderD[nu, z]", "ParabolicCylinderD[nu, z]", 0);
    assert_true("NumericQ[ParabolicCylinderD[1, 2]]");
    assert_true("!NumericQ[ParabolicCylinderD[nu, 2]]");
    assert_true("N[ParabolicCylinderD[1, 2]] == 2 Exp[-1.]");
}

/* ---- machine numerics ------------------------------------------------ */

void test_pcfd_machine_real() {
    char buf[256];
    for (size_t i = 0; i < sizeof(PCFD_REAL) / sizeof(PCFD_REAL[0]); i++) {
        char b0[64], b1[64];
        snprintf(buf, sizeof buf, "ParabolicCylinderD[%s, %s]",
                 R(PCFD_REAL[i][0], b0), R(PCFD_REAL[i][1], b1));
        double v = eval_real(buf), e = PCFD_REAL[i][2];
        ASSERT_MSG(fabs(v - e) <= PCFD_TOL * fabs(e),
                   "%s: expected %.17g, got %.17g", buf, e, v);
    }
    /* a machine-precision call answers with a machine number */
    assert_true("MachineNumberQ[ParabolicCylinderD[2.5, 3.]]");
    assert_true("MachineNumberQ[ParabolicCylinderD[3, 1.5]]");     /* exact order */
    assert_true("ParabolicCylinderD[3, 1.5] == ParabolicCylinderD[3., 1.5]");
}

void test_pcfd_machine_complex() {
    char buf[256];
    for (size_t i = 0; i < sizeof(PCFD_CPLX) / sizeof(PCFD_CPLX[0]); i++) {
        char b0[64], b1[64], b2[64];
        snprintf(buf, sizeof buf, "ParabolicCylinderD[%s, Complex[%s, %s]]",
                 R(PCFD_CPLX[i][0], b0), R(PCFD_CPLX[i][1], b1), R(PCFD_CPLX[i][2], b2));
        double re, im;
        eval_complex(buf, &re, &im);
        double er = PCFD_CPLX[i][3], ei = PCFD_CPLX[i][4];
        ASSERT_MSG(hypot(re - er, im - ei) <= PCFD_TOL * hypot(er, ei),
                   "%s: expected %.17g + %.17g I, got %.17g + %.17g I", buf, er, ei, re, im);
    }
    for (size_t i = 0; i < sizeof(PCFD_CNU) / sizeof(PCFD_CNU[0]); i++) {
        char b0[64], b1[64], b2[64], b3[64];
        snprintf(buf, sizeof buf,
                 "ParabolicCylinderD[Complex[%s, %s], Complex[%s, %s]]",
                 R(PCFD_CNU[i][0], b0), R(PCFD_CNU[i][1], b1),
                 R(PCFD_CNU[i][2], b2), R(PCFD_CNU[i][3], b3));
        double re, im;
        eval_complex(buf, &re, &im);
        double er = PCFD_CNU[i][4], ei = PCFD_CNU[i][5];
        ASSERT_MSG(hypot(re - er, im - ei) <= PCFD_TOL * hypot(er, ei),
                   "%s: expected %.17g + %.17g I, got %.17g + %.17g I", buf, er, ei, re, im);
    }
    /* a complex argument gives a machine Complex */
    assert_eval_eq("Head[ParabolicCylinderD[2.5, 3. + 1. I]]", "Complex", 0);
    /* conjugate symmetry for real order */
    assert_true("ParabolicCylinderD[1.7, 2. - 3. I] == Conjugate[ParabolicCylinderD[1.7, 2. + 3. I]]");
}

/* never inf.0 / 0.: the value leaves the double range as an extended-range real */
void test_pcfd_range() {
    assert_true("Abs[ParabolicCylinderD[2.5, 60.]/(3.8029284557668268`16*^-387) - 1] < 10^-12");
    assert_true("Abs[ParabolicCylinderD[2.5, -60.]/(-1.1640508397022717`16*^385) - 1] < 10^-12");
    assert_true("ParabolicCylinderD[2.5, 60.] != 0");
    assert_true("Abs[ParabolicCylinderD[0.5, 1000.]] > 0");
    /* Past MPFR's exponent range (|D| ~ 10^-(1.1*10^15) at z = 10^8): an
     * underflow is 0., and a growth is Overflow[], as for Exp.  The value
     * used to carry an out-of-range MPFR exponent: it printed, but r 2 was
     * 0.e-15 and r r exhausted GMP memory (the kernel aborted), which took
     * down NIntegrate of a product of two D's on (0, Infinity) (G&R 7.755.1). */
    assert_eval_eq("ParabolicCylinderD[7/3, 1.*^8]", "0.0", 0);
    assert_eval_eq("ParabolicCylinderD[-7/3, -1.*^8]", "Overflow[]", 0);
    assert_true("With[{r = ParabolicCylinderD[7/3, 1.*^8]}, r r == 0 && 2 r == 0]");
    assert_true("Abs[NIntegrate[x^(-1/2) ParabolicCylinderD[7/3, Sqrt[x/5]] "
                "ParabolicCylinderD[-10/3, Sqrt[x/5]] BesselJ[0, 3 x/8], {x, 0, Infinity}]"
                " + 1.0742225188897642] < 10^-4");
}

/* ---- arbitrary precision -------------------------------------------- */

void test_pcfd_arbitrary() {
    char buf[512];
    for (size_t i = 0; i < sizeof(PCFD_MP) / sizeof(PCFD_MP[0]); i++) {
        snprintf(buf, sizeof buf,
                 "With[{v = N[ParabolicCylinderD[%s, %s], 40], r = %s}, "
                 "Abs[v - r] <= 10^-38 Abs[r] && Precision[v] >= 39]",
                 PCFD_MP[i][0], PCFD_MP[i][1], PCFD_MP[i][2]);
        assert_true(buf);
    }
    snprintf(buf, sizeof buf,
             "With[{v = N[ParabolicCylinderD[1/3 + I/2, -2 + 3 I/2], 40], "
             "r = %s + %s I}, Abs[v - r] <= 10^-38 Abs[r]]",
             PCFD_MP_C[0], PCFD_MP_C[1]);
    assert_true(buf);
    /* an MPFR argument sets the precision */
    assert_true("Precision[ParabolicCylinderD[2.5`30, 3]] >= 29");
    /* 200 digits agrees with 100 digits to 100 */
    assert_true("Abs[N[ParabolicCylinderD[2/3, 5/4], 200] - N[ParabolicCylinderD[2/3, 5/4], 100]] < 10^-98");
}

/* ---- identities ------------------------------------------------------ */

void test_pcfd_identities() {
    /* three-term recurrence D_{nu+1} - z D_nu + nu D_{nu-1} = 0 (DLMF 12.8.1) */
    assert_true("With[{nu = 1/3`45, z = 7/10`45}, Abs[ParabolicCylinderD[nu + 1, z] - z ParabolicCylinderD[nu, z] + nu ParabolicCylinderD[nu - 1, z]] < 10^-38]");
    assert_true("With[{nu = 2.7, z = -3.1}, Abs[ParabolicCylinderD[nu + 1, z] - z ParabolicCylinderD[nu, z] + nu ParabolicCylinderD[nu - 1, z]] < 10^-12]");
    assert_true("With[{nu = -4.2, z = 6.5}, Abs[ParabolicCylinderD[nu + 1, z] - z ParabolicCylinderD[nu, z] + nu ParabolicCylinderD[nu - 1, z]] < 10^-14 Abs[z ParabolicCylinderD[nu, z]]]");
    /* Wronskian W{D_nu(z), D_nu(-z)} = Sqrt[2 Pi]/Gamma[-nu] (DLMF 12.2.11) */
    assert_true("With[{nu = 1/3`45, z = 7/10`45}, Module[{d = ParabolicCylinderD, dp},"
                " dp[n_, x_] := x/2 d[n, x] - d[n + 1, x];"
                " Abs[d[nu, z] (-dp[nu, -z]) - dp[nu, z] d[nu, -z] - Sqrt[2 Pi]/Gamma[-nu]] < 10^-37]]");
    /* the ODE w'' = (z^2/4 - nu - 1/2) w through the D rule */
    assert_true("With[{w = D[ParabolicCylinderD[2/3, z], {z, 2}] - (z^2/4 - 2/3 - 1/2) ParabolicCylinderD[2/3, z]}, Abs[w /. z -> 1.1] < 10^-13]");
    /* D_{-1}(z) = E^(z^2/4) Sqrt[Pi/2] Erfc[z/Sqrt[2]] */
    assert_true("Abs[ParabolicCylinderD[-1., 1.3] - E^(1.3^2/4) Sqrt[Pi/2] Erfc[1.3/Sqrt[2]]] < 10^-15");
    /* integer orders: D_n(-z) = (-1)^n D_n(z) */
    assert_true("Abs[ParabolicCylinderD[5., -2.2] + ParabolicCylinderD[5., 2.2]] < 10^-14");
    /* DLMF 12.7.14: the U form */
    assert_true("Abs[ParabolicCylinderD[3/5`35, 2] - 2^(3/10) E^(-1) HypergeometricU[-3/10`35, 1/2, 2]] < 10^-28");
}

void test_pcfd_function_expand() {
    assert_true("FunctionExpand[ParabolicCylinderD[0, z]] === E^(-z^2/4)");
    assert_true("Simplify[FunctionExpand[ParabolicCylinderD[3, z]] - 2^(-3/2) E^(-z^2/4) HermiteH[3, z/Sqrt[2]]] === 0");
    assert_true("Simplify[FunctionExpand[ParabolicCylinderD[-1, z]] - E^(z^2/4) Sqrt[Pi/2] Erfc[z/Sqrt[2]]] === 0");
    for (int n = -5; n <= 6; n++) {
        char buf[256];
        snprintf(buf, sizeof buf,
                 "Abs[(FunctionExpand[ParabolicCylinderD[%d, z]] /. z -> 13/10) - N[ParabolicCylinderD[%d, 13/10], 30]] < 10^-25",
                 n, n);
        assert_true(buf);
    }
    /* a non-integer order is left alone */
    assert_eval_eq("FunctionExpand[ParabolicCylinderD[1/2, z]]", "ParabolicCylinderD[1/2, z]", 0);
}

/* ---- calculus -------------------------------------------------------- */

void test_pcfd_derivative() {
    assert_true("D[ParabolicCylinderD[nu, z], z] === z/2 ParabolicCylinderD[nu, z] - ParabolicCylinderD[1 + nu, z]");
    assert_true("D[ParabolicCylinderD[nu, x^2], x] === 2 x (x^2/2 ParabolicCylinderD[nu, x^2] - ParabolicCylinderD[1 + nu, x^2])");
    assert_true("D[ParabolicCylinderD[nu, z], nu] === Derivative[1, 0][ParabolicCylinderD][nu, z]");
    assert_true("D[ParabolicCylinderD[3, z], nu] === 0");
    /* the derivative agrees with a numerical one */
    assert_true("Abs[(D[ParabolicCylinderD[1.3, z], z] /. z -> 0.9) - (ParabolicCylinderD[1.3, 0.9 + 10.^-5] - ParabolicCylinderD[1.3, 0.9 - 10.^-5])/(2 10.^-5)] < 10^-8");
}

void test_pcfd_series() {
    assert_true("Normal[Series[ParabolicCylinderD[0, z], {z, 0, 4}]] === 1 - z^2/4 + z^4/32");
    assert_true("Simplify[Normal[Series[ParabolicCylinderD[nu, z], {z, 0, 1}]] - (2^(nu/2) Sqrt[Pi]/Gamma[(1 - nu)/2] - 2^((1 + nu)/2) Sqrt[Pi] z/Gamma[-nu/2])] === 0");
}

/* ---- threading, buffers, Compile ------------------------------------- */

void test_pcfd_listable() {
    assert_true("ParabolicCylinderD[{1.5, 2.5}, 3.] === {ParabolicCylinderD[1.5, 3.], ParabolicCylinderD[2.5, 3.]}");
    assert_true("ParabolicCylinderD[2.5, {1., -2.}] === {ParabolicCylinderD[2.5, 1.], ParabolicCylinderD[2.5, -2.]}");
    assert_true("ParabolicCylinderD[nu, {0, z}] === {2^(nu/2) Sqrt[Pi]/Gamma[1/2 - nu/2], ParabolicCylinderD[nu, z]}");
}

void test_pcfd_buffers() {
    /* packed in, packed out, bit-for-bit the scalar, over every kernel branch */
    assert_true("PackedArrayQ[ParabolicCylinderD[2.5, Range[-30., 30., 0.01]]]");
    assert_true("With[{v = Range[-30., 30., 0.01]}, ParabolicCylinderD[2.5, v] === Table[ParabolicCylinderD[2.5, x], {x, FromPackedArray[v]}]]");
    assert_true("With[{v = Range[-20., 20., 0.05]}, ParabolicCylinderD[-17.3, v] === Table[ParabolicCylinderD[-17.3, x], {x, FromPackedArray[v]}]]");
    assert_true("With[{v = Range[-10., 10., 0.1]}, ParabolicCylinderD[55.5, v] === Table[ParabolicCylinderD[55.5, x], {x, FromPackedArray[v]}]]");
    /* an order buffer */
    assert_true("With[{v = Range[-5., 5., 0.1]}, ParabolicCylinderD[v, 1.7] === Table[ParabolicCylinderD[n, 1.7], {n, FromPackedArray[v]}]]");
    /* a visible NDArray, real and complex */
    assert_eval_eq("Head[ParabolicCylinderD[2.5, NDArray[{1.5, 2.5, -3.5}]]]", "NDArray", 0);
    assert_true("With[{v = Range[-3., 3., 0.25]}, Normal[ParabolicCylinderD[0.7, NDArray[v]]] === ParabolicCylinderD[0.7, FromPackedArray[v]]]");
    assert_true("With[{v = Range[-3., 3., 0.25] + 0.4 I}, Normal[ParabolicCylinderD[0.7, NDArray[v]]] === ParabolicCylinderD[0.7, FromPackedArray[v]]]");
    assert_true("With[{v = Range[-3., 3., 0.25] + 0.4 I}, PackedArrayQ[ParabolicCylinderD[0.7, v]]]");
    /* a complex order over a real buffer */
    assert_true("With[{v = Range[-2., 2., 0.5]}, Normal[ParabolicCylinderD[0.5 + 0.5 I, NDArray[v]]] === ParabolicCylinderD[0.5 + 0.5 I, FromPackedArray[v]]]");
    /* an int64 buffer holds exact values: exact element-wise rules */
    assert_true("ParabolicCylinderD[nu, NDArray[{0, 0}, DataType -> \"int64\"]][[1]] === 2^(nu/2) Sqrt[Pi]/Gamma[1/2 - nu/2]");
    /* an out-of-range element is still answered (extended range) */
    assert_true("With[{r = ParabolicCylinderD[2.5, {1., 60.}]}, r[[1]] == ParabolicCylinderD[2.5, 1.] && r[[2]] != 0]");
}

void test_pcfd_compile() {
    assert_eval_eq("CompileDiagnostics[{{x, _Real}}, ParabolicCylinderD[2.5, x]][[1]]",
                   "\"Compiled\" -> True", 0);
    assert_eval_eq("CompileDiagnostics[{{v, _Real, 1}}, ParabolicCylinderD[2.5, v]][[1]]",
                   "\"Compiled\" -> True", 0);
    assert_true("With[{f = Compile[{{x, _Real}}, ParabolicCylinderD[2.5, x]]}, "
                "And @@ Table[f[x] === ParabolicCylinderD[2.5, x], {x, -12., 12., 0.37}]]");
    assert_true("With[{f = Compile[{{v, _Real, 1}}, ParabolicCylinderD[-1.25, v]], v = Range[-9., 9., 0.01]}, "
                "f[v] === ParabolicCylinderD[-1.25, v]]");
    assert_true("With[{f = Compile[{{n, _Real}, {x, _Real}}, ParabolicCylinderD[n, x] + x]}, "
                "f[3.3, 1.1] === ParabolicCylinderD[3.3, 1.1] + 1.1]");
}

/* ---- messages and attributes ----------------------------------------- */

void test_pcfd_messages() {
    test_mute_messages();
    assert_eval_eq("Check[ParabolicCylinderD[1.], \"failed\"]", "\"failed\"", 0);
    assert_eval_eq("Check[ParabolicCylinderD[1., 2., 3.], \"failed\"]", "\"failed\"", 0);
    assert_eval_eq("Quiet[ParabolicCylinderD[x]]", "ParabolicCylinderD[x]", 0);
    assert_eval_eq("Check[ParabolicCylinderD[2.5, 3.], \"failed\"]",
                   "1.29848", 0);
}

void test_pcfd_attributes() {
    assert_eval_eq("Attributes[ParabolicCylinderD]",
                   "{Listable, NumericFunction, Protected}", 0);
    SymbolDef* d = symtab_get_def("ParabolicCylinderD");
    ASSERT(d != NULL && d->docstring != NULL && strstr(d->docstring, "ParabolicCylinderD[nu, z]"));
}

